const t=[{id:"l.rc-shallow.shear-out",xp:40,title:{en:"Untick the code iteration and deepen d until a d/2 shear line leaves the footing",ar:"شيل علامة خطوات الكود وعمّق d لحد ما خط قص d/2 يطلع برّه القاعدة"},check:e=>e.mode==="isolated"&&e.explore&&e.shearOut},{id:"l.rc-shallow.long-col",xp:40,title:{en:"Stretch the column (b > 2a) until 0.316(0.5 + a/b)√(fcu/γc) becomes the governing punching limit",ar:"طوّل العمود (b > 2a) لحد ما 0.316(0.5 + a/b)√(fcu/γc) يبقى الحد الحاكم للقص الثاقب"},check:e=>e.mode==="isolated"&&e.isoKind==="column"&&e.punchGov===1}],a=[{id:"l.rc-shallow.uniform",xp:40,title:{en:"Slide the footing until the soil pressure is uniform",ar:"رحّل القاعدة لحد ما ضغط التربة يبقى منتظم"},check:e=>e.mode==="moments"&&e.momKind==="permanent"&&e.e>.02&&e.uniform},{id:"l.rc-shallow.tension",xp:40,title:{en:"Switch to a temporary moment and raise it until F2 < 0",ar:"حوّل لعزم مؤقت وزوّده لحد ما F2 < 0"},check:e=>e.mode==="moments"&&e.momKind==="temporary"&&e.F2neg}],n=[{id:"l.rc-shallow.mid",xp:30,title:{en:"Make both columns equally loaded: the resultant moves to mid-spacing",ar:"خلّي حمل العمودين متساوي: المحصلة بتروح لنص المسافة"},check:e=>e.mode==="combined"&&e.resultantMid},{id:"l.rc-shallow.no-deepen",xp:50,title:{en:"Find loads or a spacing where the hidden beams pass at the first depth (no deepening) while the isolated footings still overlap",ar:"دوّر على أحمال أو مسافة تخلّي الكمرات المدفونة تعدّي من أول عمق (من غير تعميق) والقواعد المنفصلة لسه متداخلة"},check:e=>e.mode==="combined"&&!e.deepened&&e.overlap}],o=[{id:"l.rc-shallow.gap",xp:50,title:{en:"Bring C2 closer until the strap fails the gap test and a combined footing takes over",ar:"قرّب C2 لحد ما كمرة التحزيم تفشل في اختبار المسافة والقاعدة المشتركة تاخد مكانها"},check:e=>e.mode==="line"&&e.seenStrap&&!e.forced&&(e.lineAuto==="rect"||e.lineAuto==="trap")},{id:"l.rc-shallow.trap",xp:50,title:{en:"Make the edge column the heavier one on a short spacing: the answer becomes a trapezoid",ar:"خلّي عمود الجار هو الأتقل على مسافة قصيرة: الحل بيبقى شبه منحرف"},check:e=>e.mode==="line"&&!e.forced&&e.lineAuto==="trap"}],i=[{id:"l.rc-shallow.bld-xray",xp:30,title:{en:"X-ray the B1–B2 strap: top bars over F1, bottom bars under C2",ar:"شغّل الأشعة على كمرة تحزيم B1–B2: الحديد العلوي فوق F1 والسفلي تحت C2"},check:e=>e.preset==="building"&&e.xray},{id:"l.rc-shallow.bld-e",xp:40,title:{en:"Push e to 1.0 m: watch R1 and the strap moment grow",ar:"زوّد e لـ 1.0 م: شوف R1 وعزم الكمرة بيكبروا"},check:e=>e.preset==="building"&&e.strapE>=1-1e-9}],s={sections:[{id:"intro",title:{en:"Shallow foundations: spreading a column over the soil",ar:"الأساسات السطحية: نفرش حمل العمود على التربة"},blocks:[{t:"p",text:{en:"A column of 350 × 550 mm carrying 1300 kN presses on its base with $1300/(0.35\\times0.55) = 6753$ kN/m², while a good soil accepts only 150–200 kN/m². A **footing** spreads that concentrated load over an area large enough for the soil, and at the same time stops the column from **punching** into the ground. It is a **shallow foundation** when it sits near the surface: the founding depth $D_f$ is not larger than its width B.",ar:"عمود 350 × 550 مم شايل 1300 kN بيضغط على قاعدته بـ $1300/(0.35\\times0.55) = 6753$ kN/m²، والتربة الكويسة مابتستحملش غير 150–200 kN/m². **القاعدة** بتفرش الحمل المركز ده على مساحة كبيرة كفاية للتربة، وفي نفس الوقت بتمنع العمود إنه **يخرم** الأرض (القص الثاقب). وبتبقى **أساسات سطحية** لما تكون قريبة من السطح: عمق التأسيس $D_f$ مش أكبر من عرضها B."}},{t:"p",text:{en:"**Rigid or flexible?** A thick, stiff footing presses the soil almost uniformly; a thin, flexible one bends, and the pressure piles up under the column. The whole design method of this episode assumes a **uniform** contact pressure — so we deliberately choose a generous depth (C1 close to 5) to keep the footing rigid.",ar:"**جاسئة ولا مرنة؟** القاعدة التخينة الجاسئة بتضغط على التربة تقريباً بانتظام؛ والرفيعة المرنة بتنحني، والضغط بيتجمع تحت العمود. طريقة التصميم في الحلقة دي كلها فارضة ضغط تلامس **منتظم** — عشان كده بنختار عمق كويس (C1 قريب من 5) عشان القاعدة تفضل جاسئة."}},{t:"table",head:[{en:"Type",ar:"النوع"},{en:"Used for",ar:"بتستخدم لـ"}],rows:[[{en:"Strip (wall) footing",ar:"قاعدة شريطية (تحت حائط)"},{en:"walls, designed per metre",ar:"الحوائط، وبتتصمم لكل متر"}],[{en:"Isolated square / rectangular",ar:"قاعدة منفصلة مربعة / مستطيلة"},{en:"one column — the usual footing",ar:"عمود واحد — القاعدة العادية"}],[{en:"Haunched (sloped top) / circular",ar:"قاعدة بميول (هانش) / دائرية"},{en:"very heavy columns (e.g. bridges) / circular columns only — costly, a square is usually used",ar:"أعمدة تقيلة جداً (زي الكباري) / أعمدة دائرية بس — مكلفة، وغالباً بيتعمل مربع"}],[{en:"Combined (rectangular / trapezoidal)",ar:"قاعدة مشتركة (مستطيلة / شبه منحرفة)"},{en:"two columns whose footings would overlap, or a column at the property line",ar:"عمودين قواعدهم هتتداخل، أو عمود عند حد الجار"}],[{en:"Strap beam and two footings",ar:"كمرة تحزيم وقاعدتين"},{en:"a column at the property line with room to spare",ar:"عمود عند حد الجار والمسافة كفاية"}],[{en:"Raft / piles",ar:"لبشة / خوازيق"},{en:"weak soil or very heavy loads (piles: the next episode)",ar:"تربة ضعيفة أو أحمال تقيلة جداً (الخوازيق: الحلقة الجاية)"}]]},{t:"p",text:{en:"Three things choose the footing: the **shape of what it carries** (a wall → strip, a column → isolated), the **loads and the spacing** of the columns (heavy loads on close columns → the footings overlap → combined), and the **property line** (a column on the neighbour's boundary cannot have a footing centred under it).",ar:"تلات حاجات بتختار القاعدة: **شكل اللي شايلاه** (حائط ← شريطية، عمود ← منفصلة)، و**الأحمال والمسافات** بين الأعمدة (أحمال تقيلة على أعمدة قريبة ← القواعد بتتداخل ← مشتركة)، و**حد الجار** (عمود على حدود الجار مايقدرش ياخد قاعدة مركزها تحته)."}},{t:"quiz",q:{kind:"mcq",q:{en:"Two heavy interior columns stand 2.4 m apart and their isolated footings would overlap. What do you use?",ar:"عمودين داخليين تقال المسافة بينهم 2.4 م وقواعدهم المنفصلة هتتداخل. هتستخدم إيه؟"},options:[{en:"A combined footing under both columns",ar:"قاعدة مشتركة تحت العمودين"},{en:"A strap beam",ar:"كمرة تحزيم"},{en:"Two strip footings",ar:"قاعدتين شريطيتين"}],answer:0,explain:{en:"Overlapping isolated footings become one combined footing whose centre sits on the resultant of the two loads. A strap is for a column at a property line.",ar:"القواعد المنفصلة المتداخلة بتبقى قاعدة مشتركة واحدة مركزها على محصلة الحملين. كمرة التحزيم لعمود عند حد الجار."}}}]},{id:"pc",title:{en:"The plain-concrete base: blinding or P.C. footing",ar:"الخرسانة العادية: فرشة نظافة ولا قاعدة خرسانة عادية"},blocks:[{t:"p",text:{en:"Every R.C. footing sits on a layer of **plain concrete** (P.C., خرسانة عادية). It levels the bottom of the excavation, keeps the bars away from the soil (and its salts), and spreads the load a little further. Its thickness decides how we count it:",ar:"كل قاعدة خرسانة مسلحة قاعدة على طبقة **خرسانة عادية** (P.C.). بتسوّي قاع الحفر، وبتبعد الحديد عن التربة (والأملاح اللي فيها)، وبتفرش الحمل شوية كمان. وتخانتها هي اللي بتحدد بنحسبها إزاي:"}},{t:"steps",items:[{en:"**10–20 cm: a blinding** (فرشة نظافة). It is ignored in the design: the area P/q_all is given to the **R.C.**, and the P.C. simply projects t_PC around it.",ar:"**10–20 سم: فرشة نظافة**. بتتهمل في التصميم: المساحة P/q_all بتتحسب على **المسلحة**، والعادية بتبرز حواليها t_PC وخلاص."},{en:"**20–40 cm: a P.C. footing**. It is part of the foundation: the area P/q_all is given to the **P.C.**, and the R.C. is 2·t_PC smaller in each direction.",ar:"**20–40 سم: قاعدة خرسانة عادية**. جزء من الأساس: المساحة P/q_all بتتحسب على **العادية**، والمسلحة أصغر منها بـ 2·t_PC في كل اتجاه."}]},{t:"eq",tex:["X = t_{PC},\\qquad B_{RC} = B_{PC} - 2t_{PC},\\qquad B_{PC} = B_{RC} + 2t_{PC}"],caption:{en:"The projection equals the thickness: the load spreads at 1:1 through the unreinforced concrete. A longer projection would crack the plain corner in diagonal tension. Plan dimensions are rounded up to 50 mm.",ar:"البروز بيساوي التخانة: الحمل بينتشر 1:1 في الخرسانة غير المسلحة. ولو البروز أطول، ركن العادية هيتشرخ من الشد القطري. ومقاسات المسقط بتتقرّب لفوق لأقرب 50 مم."}},{t:"p",text:{en:"**Example.** $P = 900$ kN, $q_{all} = 150$ kN/m² → $A = 900/150 = 6.0$ m². (a) A 30 cm P.C. footing: $B_{PC} = \\sqrt{6.0} = 2.449$ → **2.45 m**, $B_{RC} = 2.45 - 0.60 = 1.85$ m. (b) A 15 cm blinding: $B_{RC} = 2.45$ m and $B_{PC} = 2.45 + 0.30 = 2.75$ m. The P.C. footing buys the same area with far less reinforced concrete — which is why it is the usual choice for columns.",ar:"**مثال.** $P = 900$ kN و $q_{all} = 150$ kN/m² ← $A = 900/150 = 6.0$ م². (أ) قاعدة عادية 30 سم: $B_{PC} = \\sqrt{6.0} = 2.449$ ← **2.45 م**، و $B_{RC} = 2.45 - 0.60 = 1.85$ م. (ب) فرشة نظافة 15 سم: $B_{RC} = 2.45$ م و $B_{PC} = 2.45 + 0.30 = 2.75$ م. القاعدة العادية بتجيب نفس المساحة بخرسانة مسلحة أقل بكتير — وده سبب إنها الاختيار المعتاد للأعمدة."}},{t:"quiz",q:{kind:"num",q:{en:"P = 1000 kN, q_all = 160 kN/m², a square footing on a 35 cm P.C. footing. B_RC (m)?",ar:"P = 1000 kN و q_all = 160 kN/m²، قاعدة مربعة على قاعدة عادية 35 سم. B_RC (م)؟"},answer:1.8,tol:.005,unit:"m",explain:{en:"$A = 1000/160 = 6.25$ m² on the P.C.: $B_{PC} = 2.50$ m, $B_{RC} = 2.50 - 2\\times0.35 = 1.80$ m.",ar:"$A = 1000/160 = 6.25$ م² على العادية: $B_{PC} = 2.50$ م، و $B_{RC} = 2.50 - 2\\times0.35 = 1.80$ م."}}}]},{id:"data",title:{en:"Design data, minimum sizes and the two shear checks",ar:"بيانات التصميم والمقاسات الدنيا ومراجعتين القص"},blocks:[{t:"p",text:{en:"A footing is designed from: the **working** column load P (kN), the column sides a × b (**a = the smaller side**), the **net** allowable soil pressure $q_{all}$, the P.C. thickness, fcu and fy. The soil is checked with working loads against $q_{all}$; the concrete is designed for the ultimate load — for foundations with a single factor:",ar:"القاعدة بتتصمم من: حمل العمود **وقت التشغيل** P (kN)، وأضلاع العمود a × b (**a = الضلع الأصغر**)، و**صافي** جهد التربة المسموح $q_{all}$، وتخانة العادية، و fcu و fy. التربة بتتراجع بأحمال التشغيل قصاد $q_{all}$؛ والخرسانة بتتصمم على الحمل الأقصى — وفي الأساسات بمعامل واحد:"}},{t:"eq",tex:["P_{UL} = 1.5\\,P,\\qquad d = C_1\\sqrt{\\frac{M}{f_{cu}\\,B}},\\qquad t = d + 70"],caption:{en:"C1 between 3.5 and 5.0 (5.0 preferred: a thick, rigid footing); t rounded up to 50 mm.",ar:"C1 بين 3.5 و 5.0 (5.0 الأفضل: قاعدة تخينة وجاسئة)؛ و t بتتقرّب لفوق لأقرب 50 مم."}},{t:"note",tone:"code",text:{en:"**Minimum R.C. footing:** B ≥ 0.80 m, t ≥ 400 mm (d ≥ 330 mm), cover to the bars 70 mm. **One-way shear** at d/2 from the face: $q_{su} = 0.16\\sqrt{f_{cu}/\\gamma_c}$ (0.653 N/mm² for fcu = 25). **Punching** at d/2 around the column: $q_{pcu}$ = the least of the four values below. Footings carry shear by the concrete alone — no stirrups — so a failed check means **t + 100 mm** and check again.",ar:"**أقل قاعدة مسلحة:** B ≥ 0.80 م، و t ≥ 400 مم (d ≥ 330 مم)، والغطاء للحديد 70 مم. **قص الاتجاه الواحد** على d/2 من الوش: $q_{su} = 0.16\\sqrt{f_{cu}/\\gamma_c}$ (0.653 N/mm² لـ fcu = 25). **القص الثاقب** على d/2 حوالين العمود: $q_{pcu}$ = أقل قيمة من الأربعة اللي تحت. القاعدة بتشيل القص بالخرسانة بس — مفيش كانات — يعني لو المراجعة فشلت يبقى **t + 100 مم** ونراجع تاني."}},{t:"eq",tex:["q_{pcu} = \\min\\left\\{0.8\\left(\\frac{\\alpha d}{b_o} + 0.2\\right)\\sqrt{\\frac{f_{cu}}{\\gamma_c}};\\ 0.316\\left(0.5 + \\frac{a}{b}\\right)\\sqrt{\\frac{f_{cu}}{\\gamma_c}};\\ 0.316\\sqrt{\\frac{f_{cu}}{\\gamma_c}};\\ 1.6\\right\\}"],caption:{en:"α = 4 for an interior column, 3 at an edge, 2 at a corner; b_o = the punching perimeter at d/2; a/b = short/long column side.",ar:"α = 4 للعمود الداخلي، و 3 عند الطرف، و 2 في الركن؛ و b_o = محيط القص الثاقب على d/2؛ و a/b = الضلع القصير/الطويل للعمود."}},{t:"p",text:{en:"**Example.** A 300 × 800 mm column with fcu = 30: $\\sqrt{30/1.5} = 4.472$, so $0.316(0.5 + 0.375)\\times4.472 = 1.237$ N/mm² — lower than $0.316\\times4.472 = 1.413$ and than 1.6. A long, narrow column spreads its load unevenly around the perimeter, and the code lowers its punching strength.",ar:"**مثال.** عمود 300 × 800 مم و fcu = 30: $\\sqrt{30/1.5} = 4.472$، يبقى $0.316(0.5 + 0.375)\\times4.472 = 1.237$ N/mm² — أقل من $0.316\\times4.472 = 1.413$ ومن 1.6. العمود الطويل الرفيع بيوزّع حمله على المحيط بشكل مش منتظم، فالكود بيقلل مقاومته للقص الثاقب."}},{t:"quiz",q:{kind:"num",q:{en:"One-way shear strength q_su of a footing with fcu = 30 N/mm² (N/mm²)?",ar:"مقاومة قص الاتجاه الواحد q_su لقاعدة بـ fcu = 30 N/mm² (N/mm²)؟"},answer:.7155,tol:.003,unit:"N/mm²",explain:{en:"$0.16\\sqrt{30/1.5} = 0.16\\times4.472 = 0.716$ N/mm².",ar:"$0.16\\sqrt{30/1.5} = 0.16\\times4.472 = 0.716$ N/mm²."}}}]},{id:"strip",title:{en:"Strip footing under a wall",ar:"القاعدة الشريطية تحت حائط"},blocks:[{t:"p",text:{en:"A wall footing is designed for **one metre of wall**: it is a pair of cantilevers sticking out from the wall faces, loaded upward by the soil. Four steps: width, moment and depth, shear, steel.",ar:"قاعدة الحائط بتتصمم لـ **متر واحد من الحائط**: هي كابوليين طالعين من وشّين الحائط، والتربة بتحمّلهم لفوق. أربع خطوات: العرض، والعزم والعمق، والقص، والحديد."}},{t:"eq",tex:["B = \\frac{P}{q_{all}},\\qquad F = \\frac{1.5\\,P}{B_{RC}},\\qquad z = \\frac{B_{RC} - b_w}{2},\\qquad M = \\frac{F\\,z^2}{2},\\qquad Q = F\\left(z - \\frac{d}{2}\\right)"],caption:{en:"Per metre of wall: P in kN/m, M in kN·m/m, Q in kN/m; b_w = wall thickness.",ar:"لكل متر من الحائط: P بالـ kN/m، و M بالـ kN·m/m، و Q بالـ kN/m؛ و b_w = تخانة الحائط."}},{t:"p",text:{en:"**Example.** A 250 mm wall with $P = 300$ kN/m, $q_{all} = 120$ kN/m², on a **20 cm blinding** (so the area goes to the R.C.): $B = 300/120 = 2.50$ m = $B_{RC}$, $B_{PC} = 2.90$ m. $F = 450/2.50 = 180$ kN/m², $z = (2.50 - 0.25)/2 = 1.125$ m, $M = 180\\times1.125^2/2 = 113.9$ kN·m/m. $d = 5\\sqrt{113.9\\times10^6/25\\,000} = 337.5$ mm → **t = 450 mm**, d = 380 mm. Shear: $l = 1.125 - 0.19 = 0.935$ m, $Q = 180\\times0.935 = 168.3$ kN/m, $q = 168\\,300/(1000\\times380) = 0.443 < 0.653$ ✓. Steel: $C_1 = 5.63$ → J = 0.826, $A_s = 113.9\\times10^6/(0.826\\times400\\times380) = 907$ mm²/m → **5Ø16/m**; secondary bars along the wall: the larger of $0.2A_s$ and $A_{s,min} = 1.5\\times380 = 570$ → **6Ø12/m**.",ar:"**مثال.** حائط 250 مم بـ $P = 300$ kN/m و $q_{all} = 120$ kN/m²، على **فرشة نظافة 20 سم** (يعني المساحة على المسلحة): $B = 300/120 = 2.50$ م = $B_{RC}$، و $B_{PC} = 2.90$ م. $F = 450/2.50 = 180$ kN/m²، و $z = (2.50 - 0.25)/2 = 1.125$ م، و $M = 180\\times1.125^2/2 = 113.9$ kN·m/m. $d = 5\\sqrt{113.9\\times10^6/25\\,000} = 337.5$ مم ← **t = 450 مم**، و d = 380 مم. القص: $l = 1.125 - 0.19 = 0.935$ م، و $Q = 180\\times0.935 = 168.3$ kN/m، و $q = 168\\,300/(1000\\times380) = 0.443 < 0.653$ ✓. الحديد: $C_1 = 5.63$ ← J = 0.826، و $A_s = 113.9\\times10^6/(0.826\\times400\\times380) = 907$ mm²/m ← **5Ø16 في المتر**؛ والحديد الثانوي موازي للحائط: الأكبر من $0.2A_s$ و $A_{s,min} = 1.5\\times380 = 570$ ← **6Ø12 في المتر**."}},{t:"quiz",q:{kind:"num",q:{en:"Wall 250 mm, P = 240 kN/m, q_all = 100 kN/m², on a 30 cm P.C. footing. Moment at the wall face (kN·m/m)?",ar:"حائط 250 مم، و P = 240 kN/m، و q_all = 100 kN/m²، على قاعدة عادية 30 سم. العزم عند وش الحائط (kN·m/m)؟"},answer:60.06,tol:.005,unit:"kN·m/m",explain:{en:"$B_{PC} = 2.40$, $B_{RC} = 1.80$ m; $F = 360/1.80 = 200$ kN/m²; $z = (1.80 - 0.25)/2 = 0.775$; $M = 200\\times0.775^2/2 = 60.06$ kN·m/m.",ar:"$B_{PC} = 2.40$ و $B_{RC} = 1.80$ م؛ و $F = 360/1.80 = 200$ kN/m²؛ و $z = (1.80 - 0.25)/2 = 0.775$؛ و $M = 200\\times0.775^2/2 = 60.06$ kN·m/m."}}}]},{id:"square",title:{en:"Isolated square footing: five steps",ar:"القاعدة المنفصلة المربعة: خمس خطوات"},blocks:[{t:"steps",items:[{en:"**Area:** $B = \\sqrt{P/q_{all}}$ on the P.C. (or on the R.C. for a blinding), rounded up to 50 mm.",ar:"**المساحة:** $B = \\sqrt{P/q_{all}}$ على العادية (أو على المسلحة لو فرشة نظافة)، متقرّبة لفوق لأقرب 50 مم."},{en:"**Moment and depth:** each side works as a cantilever from the column face over the full width: $M = (F\\,z\\,B)\\,z/2$. The **smaller** column side leaves the longer projection and governs.",ar:"**العزم والعمق:** كل ناحية بتشتغل كابولي من وش العمود على العرض كله: $M = (F\\,z\\,B)\\,z/2$. **الضلع الأصغر** للعمود بيسيب البروز الأطول وهو اللي بيحكم."},{en:"**One-way shear** at d/2 from the face: $Q = F\\,l\\,B$ with $l = z - d/2$.",ar:"**قص الاتجاه الواحد** على d/2 من الوش: $Q = F\\,l\\,B$ حيث $l = z - d/2$."},{en:"**Punching** on the perimeter at d/2: $Q_p = P_{UL} - F(a + d)(b + d)$, $b_o = 2[(a + d) + (b + d)]$.",ar:"**القص الثاقب** على المحيط عند d/2: $Q_p = P_{UL} - F(a + d)(b + d)$، و $b_o = 2[(a + d) + (b + d)]$."},{en:"**Steel** per metre both ways: $A_s = M/(J f_y d)$, not less than the minimum.",ar:"**الحديد** في المتر في الاتجاهين: $A_s = M/(J f_y d)$، ومش أقل من الحد الأدنى."}]},{t:"eq",tex:["F = \\frac{P_{UL}}{B^2},\\qquad M = \\frac{F\\,z\\,B\\,z}{2},\\qquad q_u = \\frac{F\\,l\\,B}{B\\,d},\\qquad q_{pu} = \\frac{P_{UL} - F(a + d)(b + d)}{b_o\\,d}"],caption:{en:"F acts on the R.C. only; the P.C. carries the same load to a larger area of soil.",ar:"F بتأثر على المسلحة بس؛ والعادية بتنقل نفس الحمل لمساحة أكبر من التربة."}},{t:"p",text:{en:"**Example.** Column 350 × 550 mm, $P = 1300$ kN, $q_{all} = 180$ kN/m², P.C. 30 cm, fcu = 25, fy = 400. $A = 7.222$ m², $\\sqrt{A} = 2.687$ → **P.C. 2.70 × 2.70**, **R.C. 2.10 × 2.10** m. $F = 1950/2.10^2 = 442.2$ kN/m². The 350 side leaves $z = (2.10 - 0.35)/2 = 0.875$ m: $M = 442.2\\times0.875\\times2.10\\times0.875/2 = 355.5$ kN·m (the other side: $z = 0.775$, 278.9 kN·m). $d = 5\\sqrt{355.5\\times10^6/(25\\times2100)} = 411.4$ mm → t = 500 mm (d = 430).",ar:"**مثال.** عمود 350 × 550 مم، و $P = 1300$ kN، و $q_{all} = 180$ kN/m²، وعادية 30 سم، و fcu = 25، و fy = 400. $A = 7.222$ م² و $\\sqrt{A} = 2.687$ ← **العادية 2.70 × 2.70**، و**المسلحة 2.10 × 2.10** م. $F = 1950/2.10^2 = 442.2$ kN/m². الضلع 350 بيسيب $z = (2.10 - 0.35)/2 = 0.875$ م: $M = 442.2\\times0.875\\times2.10\\times0.875/2 = 355.5$ kN·m (الناحية التانية: $z = 0.775$ و 278.9 kN·m). $d = 5\\sqrt{355.5\\times10^6/(25\\times2100)} = 411.4$ مم ← t = 500 مم (d = 430)."}},{t:"p",text:{en:"**Shear decides t.** At d = 430: $l = 0.875 - 0.215 = 0.660$ m, $Q = 442.2\\times0.660 = 291.8$ kN/m, $q = 0.679 > 0.653$ ✗ → **t = 600 mm** (d = 530): $l = 0.610$, $Q = 269.7$ kN/m, $q = 0.509$ ✓. **Punching:** $Q_p = 1950 - 442.2\\times0.88\\times1.08 = 1529.8$ kN, $b_o = 2(880 + 1080) = 3920$ mm, $q_{pu} = 1\\,529\\,800/(3920\\times530) = 0.736$ N/mm² against $q_{pcu} = \\min(2.42;\\ 1.466;\\ 1.290;\\ 1.6) = 1.29$ ✓. **Steel:** $A_s = 355.5\\times10^6/(0.826\\times400\\times530) = 2030$ mm² over 2.10 m = 967 mm²/m → **5Ø16/m**; the other way 758 mm²/m < $A_{s,min} = 1.5\\times530 = 795$ → **8Ø12/m** (or 5Ø16/m both ways for one bar size).",ar:"**القص هو اللي بيحدد t.** عند d = 430: $l = 0.875 - 0.215 = 0.660$ م، و $Q = 442.2\\times0.660 = 291.8$ kN/m، و $q = 0.679 > 0.653$ ✗ ← **t = 600 مم** (d = 530): $l = 0.610$، و $Q = 269.7$ kN/m، و $q = 0.509$ ✓. **القص الثاقب:** $Q_p = 1950 - 442.2\\times0.88\\times1.08 = 1529.8$ kN، و $b_o = 2(880 + 1080) = 3920$ مم، و $q_{pu} = 1\\,529\\,800/(3920\\times530) = 0.736$ N/mm² قصاد $q_{pcu} = \\min(2.42;\\ 1.466;\\ 1.290;\\ 1.6) = 1.29$ ✓. **الحديد:** $A_s = 355.5\\times10^6/(0.826\\times400\\times530) = 2030$ مم² على 2.10 م = 967 mm²/m ← **5Ø16 في المتر**؛ والاتجاه التاني 758 mm²/m < $A_{s,min} = 1.5\\times530 = 795$ ← **8Ø12 في المتر** (أو 5Ø16 في الاتجاهين عشان مقاس واحد)."}},{t:"lab",lab:"footing",height:480,props:{preset:"square",missions:t},caption:{en:'The critical-section explorer: untick "t by the code iteration" and slide d (or drag the punching perimeter on the plan). The shear planes turn red, green or vanish, the perimeter loses faces at the footing edges, and the four q_pcu bars in Results light the governing one.',ar:'مستكشف القطاعات الحرجة: شيل علامة "t بخطوات الكود" وحرّك d (أو اسحب محيط القص الثاقب على المسقط). مستويات القص بتحمرّ أو تخضرّ أو تختفي، والمحيط بيخسر وشوش عند أحرف القاعدة، وأعمدة q_pcu الأربعة في النتائج بتنوّر الحاكم.'}},{t:"quiz",q:{kind:"num",q:{en:"R.C. footing 2.4 × 2.4 m under a 0.4 × 0.4 m column, F = 400 kN/m². Moment at the column face (kN·m)?",ar:"قاعدة مسلحة 2.4 × 2.4 م تحت عمود 0.4 × 0.4 م، و F = 400 kN/m². العزم عند وش العمود (kN·m)؟"},answer:480,tol:.003,unit:"kN·m",explain:{en:"$z = (2.4 - 0.4)/2 = 1.0$ m; $M = 400\\times1.0\\times2.4\\times1.0/2 = 480$ kN·m over the 2.4 m width.",ar:"$z = (2.4 - 0.4)/2 = 1.0$ م؛ و $M = 400\\times1.0\\times2.4\\times1.0/2 = 480$ kN·m على العرض 2.4 م."}}}]},{id:"rect",title:{en:"Isolated rectangular footing and sections outside the footing",ar:"القاعدة المنفصلة المستطيلة والقطاعات اللي برّه القاعدة"},blocks:[{t:"p",text:{en:"Under a long column a square footing wastes concrete on one side. The usual rectangle keeps **equal projections**: $L - B = b - a$ with $B\\,L = A$. Equal projections give the same moment per metre both ways — one depth and the same bars in both directions (preferred, not mandatory).",ar:"تحت عمود طويل القاعدة المربعة بتهدر خرسانة في ناحية. المستطيل المعتاد بيحافظ على **بروزات متساوية**: $L - B = b - a$ مع $B\\,L = A$. البروزات المتساوية بتدي نفس العزم في المتر في الاتجاهين — عمق واحد ونفس الحديد في الاتجاهين (مفضّل مش إلزامي)."}},{t:"eq",tex:["B\\,(B + b - a) = A,\\qquad M_I = \\frac{F\\,z\\,B\\,z}{2},\\qquad M_{II} = \\frac{F\\,z\\,L\\,z}{2}"],caption:{en:"M_I acts over the width B, M_II over the length L; with equal projections M/B = M/L per metre.",ar:"M_I على العرض B و M_II على الطول L؛ ومع البروزات المتساوية M/B = M/L في المتر."}},{t:"p",text:{en:"**Example.** Column 300 × 800 mm, $P = 1700$ kN, $q_{all} = 130$ kN/m², P.C. 30 cm, fcu = 30. $A = 13.08$ m², $B(B + 0.5) = 13.08$ → B = 3.38 → **P.C. 3.40 × 3.90**, **R.C. 2.80 × 3.30** m; $F = 2550/9.24 = 276.0$ kN/m²; both projections 1.25 m: $M_I = 603.7$ kN·m (over 2.80) and $M_{II} = 711.5$ kN·m (over 3.30) — 215.6 kN·m/m each. $d = 423.9$ → t = 500 (d = 430): shear $q = 276.0\\times1.035/430 = 0.664 < 0.716$ ✓, but **punching** $Q_p = 2550 - 276.0\\times0.73\\times1.23 = 2302.2$ kN, $b_o = 3920$ mm, $q_{pu} = 1.366 > 1.237$ — the long-column limit governs ✗ → **t = 600** (d = 530): $Q_p = 2245.4$ kN, $b_o = 4320$ mm, $q_{pu} = 0.981$ ✓. Steel 1231 mm²/m both ways → **7Ø16/m**.",ar:"**مثال.** عمود 300 × 800 مم، و $P = 1700$ kN، و $q_{all} = 130$ kN/m²، وعادية 30 سم، و fcu = 30. $A = 13.08$ م²، و $B(B + 0.5) = 13.08$ ← B = 3.38 ← **العادية 3.40 × 3.90**، و**المسلحة 2.80 × 3.30** م؛ و $F = 2550/9.24 = 276.0$ kN/m²؛ والبروزين 1.25 م: $M_I = 603.7$ kN·m (على 2.80) و $M_{II} = 711.5$ kN·m (على 3.30) — 215.6 kN·m/m لكل واحد. $d = 423.9$ ← t = 500 (d = 430): القص $q = 276.0\\times1.035/430 = 0.664 < 0.716$ ✓، بس **القص الثاقب** $Q_p = 2550 - 276.0\\times0.73\\times1.23 = 2302.2$ kN، و $b_o = 3920$ مم، و $q_{pu} = 1.366 > 1.237$ — حد العمود الطويل هو الحاكم ✗ ← **t = 600** (d = 530): $Q_p = 2245.4$ kN، و $b_o = 4320$ مم، و $q_{pu} = 0.981$ ✓. والحديد 1231 mm²/m في الاتجاهين ← **7Ø16 في المتر**."}},{t:"p",text:{en:"**When a critical section leaves the footing.** In a small, deep footing the line at d/2 from a face may fall beyond the footing edge: there is then **no one-way shear** that way (Q = 0). The punching perimeter may cross two opposite edges: only the two faces left inside resist. If it crosses all four edges, the whole footing is inside the punching cone and there is nothing to check.",ar:"**لما القطاع الحرج يطلع برّه القاعدة.** في قاعدة صغيرة وعميقة الخط اللي على d/2 من الوش ممكن يقع بعد حرف القاعدة: ساعتها **مفيش قص اتجاه واحد** في الاتجاه ده (Q = 0). ومحيط القص الثاقب ممكن يعدّي حرفين متقابلين: الوشّين اللي فضلوا جوه بس هما اللي بيقاوموا. ولو عدّى الأربع حروف، القاعدة كلها جوه مخروط القص ومفيش حاجة تتراجع."}},{t:"eq",tex:["b_o = 2\\,y,\\qquad A_p = 2\\,y\\,d,\\qquad Q_p = P_{UL} - F\\,X\\,y,\\qquad X = a + d"],caption:{en:"Two-face punching: y is the footing side the two remaining faces run along; X the extent of the perimeter across them.",ar:"قص ثاقب على وشّين: y ضلع القاعدة اللي الوشّين الباقيين ماشيين عليه؛ و X امتداد المحيط في الاتجاه التاني."}},{t:"quiz",q:{kind:"num",q:{en:"Square R.C. footing 1.60 × 1.60 m, column 0.30 × 0.80 m, d = 1000 mm. The resisting punching length b_o (mm)?",ar:"قاعدة مسلحة مربعة 1.60 × 1.60 م، وعمود 0.30 × 0.80 م، و d = 1000 مم. طول مقاومة القص الثاقب b_o (مم)؟"},answer:3200,tol:.001,unit:"mm",explain:{en:"$a + d = 1.30 < 1.60$ stays inside, $b + d = 1.80 > 1.60$ crosses the edges: the two faces along the footing remain, each 1.60 m → $b_o = 2\\times1600 = 3200$ mm.",ar:"$a + d = 1.30 < 1.60$ جوه، و $b + d = 1.80 > 1.60$ بيعدّي الحروف: الوشّين اللي على طول القاعدة فضلوا، كل واحد 1.60 م ← $b_o = 2\\times1600 = 3200$ مم."}}}]},{id:"rft",title:{en:"Reinforcement and drawing rules",ar:"قواعد التسليح والرسم"},blocks:[{t:"note",tone:"code",text:{en:"**Bars:** Ø12 at least, 5 to 10 bars per metre. **Minimum:** $A_{s,min}$ = the larger of $1.5\\,d$ mm²/m (d in mm) and 5Ø12/m = 565 mm²/m. Isolated and strip footings need a **bottom mesh** only; a **top mesh 5Ø12/m** both ways is added when **t ≥ 1.0 m**. Combined footings and strap beams have top and bottom steel.",ar:"**الأسياخ:** Ø12 على الأقل، من 5 لـ 10 أسياخ في المتر. **الحد الأدنى:** $A_{s,min}$ = الأكبر من $1.5\\,d$ mm²/m (d بالمم) و 5Ø12 في المتر = 565 mm²/m. القواعد المنفصلة والشريطية محتاجة **شبكة سفلية** بس؛ و**شبكة علوية 5Ø12 في المتر** في الاتجاهين بتتضاف لما **t ≥ 1.0 م**. والقواعد المشتركة وكمرات التحزيم فيها حديد علوي وسفلي."}},{t:"p",text:{en:"The ends of the bottom bars are bent up at the footing edges, and a **tie bar** (سيخ تربيط, 1Ø12) runs around the top of those bent ends to hold the cage. The column **dowels** (الأشاير) stand on the bottom mesh, tied to it, and are anchored at least 40Ø into the footing; they continue max(40Ø, 1.0 m) into the column to lap with its bars.",ar:"أطراف الحديد السفلي بتتركّب لفوق عند أحرف القاعدة، و**سيخ تربيط** (1Ø12) بيلف حوالين أعلى الأطراف المركّبة دي عشان يمسك القفص. و**أشاير** العمود واقفة على الشبكة السفلية ومربوطة فيها، ومتثبتة على الأقل 40Ø جوه القاعدة؛ وبتكمّل max(40Ø، 1.0 م) جوه العمود عشان تتراكب مع حديده."}},{t:"p",text:{en:"**Drawing.** The plan shows the P.C. (thin line) and the R.C. (thick line) with their dimensions and the column; the section shows the bars, the 70 mm cover and **four levels**: the ground (±0.00), the top of the R.C., the top of the P.C. and the **foundation level** (منسوب التأسيس) under the P.C. The foundation level is at least about 1.50 m below the ground.",ar:"**الرسم.** المسقط بيبيّن العادية (خط رفيع) والمسلحة (خط تقيل) بمقاساتهم والعمود؛ والقطاع بيبيّن الحديد والغطاء 70 مم و**أربع مناسيب**: الأرض (±0.00)، وظهر المسلحة، وظهر العادية، و**منسوب التأسيس** تحت العادية. ومنسوب التأسيس على الأقل حوالي 1.50 م تحت الأرض."}},{t:"table",head:[{en:"Level (square example)",ar:"المنسوب (مثال القاعدة المربعة)"},{en:"Value (m)",ar:"القيمة (م)"}],rows:[[{en:"ground",ar:"الأرض"},"±0.00"],[{en:"top of the R.C. (t = 600 mm)",ar:"ظهر المسلحة (t = 600 مم)"},"−0.60"],[{en:"top of the P.C. (30 cm)",ar:"ظهر العادية (30 سم)"},"−1.20"],[{en:"foundation level",ar:"منسوب التأسيس"},"−1.50"]],caption:{en:"Founding depth D_f = 1.50 m: foundation −1.50, then + t_PC and + t upward.",ar:"عمق التأسيس D_f = 1.50 م: التأسيس −1.50، وبعدين + t_PC و + t لفوق."}},{t:"quiz",q:{kind:"num",q:{en:"Foundation level −1.80, P.C. 30 cm, R.C. 700 mm. Level of the top of the R.C. (m)?",ar:"منسوب التأسيس −1.80، والعادية 30 سم، والمسلحة 700 مم. منسوب ظهر المسلحة (م)؟"},answer:-.8,tol:.005,unit:"m",explain:{en:"$-1.80 + 0.30 + 0.70 = -0.80$ m.",ar:"$-1.80 + 0.30 + 0.70 = -0.80$ م."}}}]},{id:"moments",title:{en:"Footings under moment: permanent moments shift the footing",ar:"القواعد تحت عزم: العزم الدائم بيرحّل القاعدة"},blocks:[{t:"p",text:{en:`Where do footing moments come from?
- the moment of a column **fixed** into the footing (a rigid frame);
- a permanent horizontal force H at a height y above the footing: $M = H\\,y$;
- the horizontal reaction X of a **hinged** frame base acting at the top of the footing: $M = X\\,t$;
- loads whose resultant misses the footing centre: $M_x = R\\,e_x$, $M_y = R\\,e_y$.`,ar:`عزوم القاعدة بتيجي منين؟
- عزم عمود **مثبّت** في القاعدة (إطار جاسئ)؛
- قوة أفقية دائمة H على ارتفاع y فوق القاعدة: $M = H\\,y$؛
- رد الفعل الأفقي X لقاعدة إطار **مفصلي** مؤثر فوق القاعدة: $M = X\\,t$؛
- أحمال محصلتها مش معدّية بمركز القاعدة: $M_x = R\\,e_x$ و $M_y = R\\,e_y$.`}},{t:"p",text:{en:"The **kind** of moment decides the method. A **permanent** moment (from dead loads) never changes value or direction, so we move the **footing** — not the column — toward it until the resultant passes through the footing centre: the soil pressure becomes uniform again and the area is simply P/q_all. A **temporary** moment (live load, wind, earthquake) can reverse; the footing stays centred and takes a trapezoidal pressure (next section).",ar:"**نوع** العزم هو اللي بيحدد الطريقة. العزم **الدائم** (من الأحمال الميتة) عمره ما بيغيّر قيمته ولا اتجاهه، فبنرحّل **القاعدة** — مش العمود — ناحيته لحد ما المحصلة تعدّي بمركز القاعدة: ضغط التربة بيرجع منتظم والمساحة ببساطة P/q_all. أما العزم **المؤقت** (حمل حي أو رياح أو زلازل) فممكن يعكس اتجاهه؛ فالقاعدة بتفضل في النص وبتاخد ضغط شبه منحرف (القسم الجاي)."}},{t:"eq",tex:["e = \\frac{M}{P},\\qquad e = \\frac{X(t_1 + t_2) + M}{P},\\qquad e_x = \\frac{M_x}{P},\\ e_y = \\frac{M_y}{P},\\qquad z = \\frac{L}{2} + e - \\frac{b}{2}"],caption:{en:"With a base shear X the moment grows by X(t1 + t2) at the underside (t1 = R.C., t2 = P.C.). The projection on the shifted side is the longer one.",ar:"مع قص أفقي X عند القاعدة العزم بيزيد X(t1 + t2) عند الوش السفلي (t1 = المسلحة و t2 = العادية). والبروز في ناحية الترحيل هو الأطول."}},{t:"p",text:{en:"**Example.** Column 400 × 600 mm, $P = 1350$ kN with a permanent moment 270 kN·m about the short axis, $q_{all} = 150$ kN/m², P.C. 30 cm. $e = 270/1350 = 0.20$ m. Uniform pressure → $A = 9.0$ m², $B(B + 0.2) = 9.0$ → **P.C. 2.95 × 3.15**, **R.C. 2.35 × 2.55** m, shifted 0.20 m. Before the shift the base would feel 89.9 … 200.6 kN/m²; after it, a uniform 145.3 kN/m². $F = 2025/(2.35\\times2.55) = 337.9$ kN/m²; the long side now projects $z = 1.275 + 0.20 - 0.30 = 1.175$ m → $M = 548.2$ kN·m (the other way $z = 0.975$, 409.6 kN·m); $d = 483$ → **t = 600 mm**; steel 1332 mm²/m → **7Ø16/m** along L, 917 → **5Ø16/m** along B.",ar:"**مثال.** عمود 400 × 600 مم، و $P = 1350$ kN مع عزم دائم 270 kN·m حوالين المحور القصير، و $q_{all} = 150$ kN/m²، وعادية 30 سم. $e = 270/1350 = 0.20$ م. الضغط المنتظم ← $A = 9.0$ م²، و $B(B + 0.2) = 9.0$ ← **العادية 2.95 × 3.15**، و**المسلحة 2.35 × 2.55** م، مرحّلة 0.20 م. قبل الترحيل القاعدة كانت هتحس بـ 89.9 … 200.6 kN/m²؛ وبعده 145.3 kN/m² منتظم. $F = 2025/(2.35\\times2.55) = 337.9$ kN/m²؛ والناحية الطويلة بقى بروزها $z = 1.275 + 0.20 - 0.30 = 1.175$ م ← $M = 548.2$ kN·m (والاتجاه التاني $z = 0.975$ و 409.6 kN·m)؛ و $d = 483$ ← **t = 600 مم**؛ والحديد 1332 mm²/m ← **7Ø16 في المتر** موازي L، و 917 ← **5Ø16 في المتر** موازي B."}},{t:"lab",lab:"footing",height:480,props:{preset:"permanent",missions:a},caption:{en:'Slide the footing with the last slider and watch the pressure surface under it flatten. Then switch to "Temporary": the footing stays put and the pressure becomes a trapezoid — red where the soil would have to pull.',ar:'رحّل القاعدة بآخر slider وشوف سطح الضغط اللي تحتها بيتفرد. وبعدين حوّل لـ "مؤقت": القاعدة بتفضل مكانها والضغط بيبقى شبه منحرف — أحمر مكان ما التربة كانت هتشد.'}},{t:"quiz",q:{kind:"num",q:{en:"P = 1600 kN, a permanent moment of 360 kN·m and a base shear of 40 kN, t1 + t2 = 1.0 m. Shift e (m)?",ar:"P = 1600 kN، وعزم دائم 360 kN·m، وقص أفقي عند القاعدة 40 kN، و t1 + t2 = 1.0 م. الترحيل e (م)؟"},answer:.25,tol:.005,unit:"m",explain:{en:"$e = (40\\times1.0 + 360)/1600 = 400/1600 = 0.25$ m.",ar:"$e = (40\\times1.0 + 360)/1600 = 400/1600 = 0.25$ م."}}}]},{id:"temporary",title:{en:"Temporary moments: the trapezoidal pressure",ar:"العزوم المؤقتة: الضغط شبه المنحرف"},blocks:[{t:"p",text:{en:"The footing stays centred on the column, with its **long side along the moment**. The soil pressure is a trapezoid, and three conditions size it: $F_1 \\le q_{all}$, $F_2 > 0$ (no tension on the soil — the soil cannot pull the footing down), and preferably $F_2 \\ge F_1/2$ (a steep trapezoid invites tilting). With $L - B = b - a$, the equation $F_1 = q_{all}$ gives B.",ar:"القاعدة بتفضل في مركز العمود، و**ضلعها الطويل مع العزم**. ضغط التربة شبه منحرف، وتلات شروط بتحدد المقاس: $F_1 \\le q_{all}$، و $F_2 > 0$ (مفيش شد على التربة — التربة مابتقدرش تشد القاعدة لتحت)، ويفضّل $F_2 \\ge F_1/2$ (شبه المنحرف الحاد بيعرّض القاعدة للدوران). ومع $L - B = b - a$، المعادلة $F_1 = q_{all}$ بتجيب B."}},{t:"eq",tex:["F_{1,2} = \\frac{P}{B\\,L} \\pm \\frac{6M}{B\\,L^2},\\qquad F_3 = \\frac{L - z_I}{L}(F_1 - F_2) + F_2,\\qquad F_{1av} = \\frac{F_1 + F_3}{2},\\qquad F_{2av} = \\frac{F_1 + F_2}{2}"],caption:{en:"Working loads for the soil, ultimate loads (1.5P, 1.5M) on the R.C. F3 is the pressure under the column face.",ar:"أحمال التشغيل للتربة، والأحمال القصوى (1.5P و 1.5M) على المسلحة. F3 هو الضغط تحت وش العمود."}},{t:"eq",tex:["M_I = \\frac{F_{1av}\\,z_I\\,B\\,z_I}{2},\\qquad M_{II} = \\frac{F_{2av}\\,z_{II}\\,L\\,z_{II}}{2},\\qquad F_4 = \\frac{L - l}{L}(F_1 - F_2) + F_2,\\qquad Q = \\frac{F_1 + F_4}{2}\\,l"],caption:{en:"Direction I runs with the moment (the heavy side governs), direction II across it with the average pressure; shear at l = z_I − d/2 with F4 under the critical line; punching with F2av.",ar:"الاتجاه I مع العزم (الناحية التقيلة هي اللي بتحكم)، والاتجاه II عمودي عليه بالضغط المتوسط؛ والقص عند l = z_I − d/2 بـ F4 تحت الخط الحرج؛ والقص الثاقب بـ F2av."}},{t:"p",text:{en:"**Example.** The same 400 × 600 column, $P = 1350$ kN, now a **temporary** moment 260 kN·m, $q_{all} = 150$, P.C. 30 cm. $F_1 = q_{all}$ → B = 3.4 → **P.C. 3.40 × 3.60**, **R.C. 2.80 × 3.00** m. Working: $F_{1,2} = 110.3 \\pm 35.4$ → $F_1 = 145.7 \\le 150$ ✓, $F_2 = 74.9 > 0$ ✓ and $\\ge F_1/2 = 72.8$ ✓. Ultimate on the R.C.: $F_1 = 333.9$, $F_2 = 148.2$ kN/m²; $z_I = 1.20$ m, $F_3 = 259.6$, $F_{1av} = 296.8$ → $M_I = 598.3$ kN·m; $F_{2av} = 241.1$ → $M_{II} = 520.7$ kN·m; d = 462 → **t = 550 mm**. Shear: $l = 0.96$ m, $F_4 = 274.5$, $Q = 304.2\\times0.96 = 292.0$ kN/m, $q = 0.608$ ✓; punching with $F_{2av}$: $q_{pu} = 0.954 < 1.29$ ✓. Steel **7Ø16/m** along L and **6Ø16/m** along B.",ar:"**مثال.** نفس العمود 400 × 600، و $P = 1350$ kN، والمرة دي عزم **مؤقت** 260 kN·m، و $q_{all} = 150$، وعادية 30 سم. $F_1 = q_{all}$ ← B = 3.4 ← **العادية 3.40 × 3.60**، و**المسلحة 2.80 × 3.00** م. التشغيل: $F_{1,2} = 110.3 \\pm 35.4$ ← $F_1 = 145.7 \\le 150$ ✓، و $F_2 = 74.9 > 0$ ✓ و $\\ge F_1/2 = 72.8$ ✓. الأقصى على المسلحة: $F_1 = 333.9$ و $F_2 = 148.2$ kN/m²؛ و $z_I = 1.20$ م، و $F_3 = 259.6$، و $F_{1av} = 296.8$ ← $M_I = 598.3$ kN·m؛ و $F_{2av} = 241.1$ ← $M_{II} = 520.7$ kN·m؛ و d = 462 ← **t = 550 مم**. القص: $l = 0.96$ م، و $F_4 = 274.5$، و $Q = 304.2\\times0.96 = 292.0$ kN/m، و $q = 0.608$ ✓؛ والقص الثاقب بـ $F_{2av}$: $q_{pu} = 0.954 < 1.29$ ✓. الحديد **7Ø16 في المتر** موازي L و**6Ø16 في المتر** موازي B."}},{t:"note",tone:"warn",text:{en:"Because the moment can reverse, the same bars go on both sides of the column. A permanent moment designed as temporary is merely uneconomical; a temporary moment treated as permanent (a shifted footing) fails the day the wind blows the other way.",ar:"لأن العزم ممكن يعكس اتجاهه، نفس الحديد بيتحط على الناحيتين. العزم الدائم لو اتصمم كمؤقت يبقى مش اقتصادي وبس؛ لكن العزم المؤقت لو اتعامل كدائم (قاعدة مرحّلة) بيفشل يوم ما الرياح تهب من الناحية التانية."}},{t:"quiz",q:{kind:"num",q:{en:"P = 1000 kN, a temporary M = 200 kN·m along the 3.0 m side of a 2.5 × 3.0 m base. F2 (kN/m²)?",ar:"P = 1000 kN، وعزم مؤقت M = 200 kN·m في اتجاه الضلع 3.0 م لقاعدة 2.5 × 3.0 م. F2 (kN/m²)؟"},answer:80,tol:.005,unit:"kN/m²",explain:{en:"$1000/7.5 - 6\\times200/(2.5\\times3.0^2) = 133.3 - 53.3 = 80.0$ kN/m² > 0 — no tension. But F1 = 186.7 and F2 < F1/2 = 93.3: a steep trapezoid, better lengthened.",ar:"$1000/7.5 - 6\\times200/(2.5\\times3.0^2) = 133.3 - 53.3 = 80.0$ kN/m² > 0 — مفيش شد. بس F1 = 186.7 و F2 < F1/2 = 93.3: شبه منحرف حاد، والأحسن نطوّلها."}}}]},{id:"combined",title:{en:"Combined footing for two interior columns",ar:"القاعدة المشتركة لعمودين داخليين"},blocks:[{t:"p",text:{en:"When the isolated footings of two neighbouring columns would overlap, one **combined footing** carries both. Its centre is placed on the **resultant** of the two loads, so the pressure stays uniform; its long axis follows the column line. It then works as an **inverted beam**: the soil pushes up a uniform load $w$ per metre, the columns hold it down.",ar:"لما القواعد المنفصلة لعمودين جنب بعض تتداخل، **قاعدة مشتركة** واحدة بتشيل الاتنين. مركزها بيتحط على **محصلة** الحملين، فالضغط بيفضل منتظم؛ ومحورها الطويل ماشي مع خط الأعمدة. وبعدين بتشتغل **ككمرة مقلوبة**: التربة بتزق حمل موزع منتظم $w$ لكل متر لفوق، والأعمدة ماسكاها لتحت."}},{t:"eq",tex:["R = P_1 + P_2,\\qquad X = \\frac{P_1\\,S}{R},\\qquad \\frac{L_{RC}}{2} = X + \\frac{b_2}{2} + (0.5 \\to 1.0),\\qquad B = \\frac{R}{q_{all}\\,L},\\qquad w = \\frac{1.5\\,R}{L}"],caption:{en:"X from the lighter column C2 toward the heavier C1; the projection beyond C2 is 0.50–1.00 m and the other end follows from symmetry about the resultant.",ar:"X من العمود الأخف C2 ناحية التقيل C1؛ والبروز بعد C2 من 0.50 لـ 1.00 م والطرف التاني بيطلع من التماثل حوالين المحصلة."}},{t:"p",text:{en:"Along the footing the moments are **bottom tension at the column faces** and **top tension between the columns**, largest where the shear is zero. Across it, each column spreads its load through a **hidden beam** (كمرة مدفونة) — a strip of width $L_1 = b + 2d$ under the column that cantilevers $z = (B - a)/2$ each side. Its depth must keep $C_1 \\ge 3$; otherwise the whole footing is deepened with $C_1 = 4.5$ and the hidden beams are checked again (they widen with d).",ar:"على طول القاعدة العزوم **شد تحت عند وشوش الأعمدة** و**شد فوق بين الأعمدة**، وأكبرها مكان ما القص = صفر. وعلى العرض، كل عمود بيوزّع حمله عن طريق **كمرة مدفونة** — شريحة عرضها $L_1 = b + 2d$ تحت العمود بتطلع كابولي $z = (B - a)/2$ من كل ناحية. وعمقها لازم يحافظ على $C_1 \\ge 3$؛ وإلا القاعدة كلها بتتعمّق بـ $C_1 = 4.5$ والكمرات المدفونة بتتراجع تاني (بتعرض مع d)."}},{t:"eq",tex:["F = \\frac{P_{u}}{B\\,L_1},\\qquad M = \\frac{F\\,z^2}{2},\\qquad C_1 = \\frac{d}{\\sqrt{M/(f_{cu}\\times1000)}} \\ge 3,\\qquad Q_{cr} = Q_{max} - w\\,\\frac{d}{2}"],caption:{en:"Hidden beam per metre (left), long shear at d/2 from the column faces (right); punching is checked at every column.",ar:"الكمرة المدفونة لكل متر (الشمال)، والقص الطولي على d/2 من وشوش الأعمدة (اليمين)؛ والقص الثاقب بيتراجع عند كل عمود."}},{t:"p",text:{en:"**Example.** C1 400 × 600 mm, $P_1 = 2000$ kN; C2 400 × 500 mm, $P_2 = 1600$ kN; $S = 2.80$ m; $q_{all} = 150$; P.C. 30 cm. Isolated P.C. footings of 3.80 and 3.35 m along the line would overlap by 0.78 m. $R = 3600$ kN, $X = 2000\\times2.8/3600 = 1.556$ m from C2 (1.244 m from C1); $L/2 = 1.556 + 0.25 + 0.75 = 2.556$ → **L = 5.15 m** (P.C. 5.75), $B_{PC} = 3600/(150\\times5.75) = 4.17$ → **4.20**, $B_{RC} = 3.60$ m. $F = 291.3$ kN/m², $w = 5400/5.15 = 1048.5$ kN/m. Moments: 556.8 kN·m at C1's outer face, zero shear 1.53 m from C1 toward C2 with **300.0 kN·m** of top tension. $d = 393$ → t = 500 (d = 430).",ar:"**مثال.** C1 400 × 600 مم و $P_1 = 2000$ kN؛ و C2 400 × 500 مم و $P_2 = 1600$ kN؛ و $S = 2.80$ م؛ و $q_{all} = 150$؛ وعادية 30 سم. القواعد المنفصلة (عاديتها 3.80 و 3.35 م على الخط) هتتداخل 0.78 م. $R = 3600$ kN، و $X = 2000\\times2.8/3600 = 1.556$ م من C2 (يعني 1.244 م من C1)؛ و $L/2 = 1.556 + 0.25 + 0.75 = 2.556$ ← **L = 5.15 م** (العادية 5.75)، و $B_{PC} = 3600/(150\\times5.75) = 4.17$ ← **4.20**، و $B_{RC} = 3.60$ م. $F = 291.3$ kN/m²، و $w = 5400/5.15 = 1048.5$ kN/m. العزوم: 556.8 kN·m عند وش C1 الخارجي، والقص = صفر على بعد 1.53 م من C1 ناحية C2 وفيه **300.0 kN·m** شد فوق. $d = 393$ ← t = 500 (d = 430)."}},{t:"p",text:{en:"**The hidden beams deepen it.** Under C1: $L_1 = 0.6 + 2\\times0.43 = 1.46$ m, $F = 3000/(3.6\\times1.46) = 570.8$, $z = 1.60$ m, $M = 730.6$ kN·m/m, $C_1 = 2.52 < 3$ ✗ (C2: 2.71 ✗) → $d = 4.5\\sqrt{730.6\\times10^6/25\\,000} = 769$ → **t = 850 mm** (d = 780). Now $L_1 = 2.16$ m, $M = 493.8$, $C_1 = 5.55$ ✓; under C2 $L_2 = 0.5 + 0.78 + 0.77 = 2.05$ m (the footing ends 0.77 m beyond C2), $C_1 = 6.04$ ✓. Long shear: $Q_{cr} = 1290.3 - 1048.5\\times0.39 = 881.4$ kN, $q = 0.314$ ✓; punching 0.632 and 0.511 < 1.29 ✓. Steel per metre: long bottom and top **6Ø16/m** (the minimum 1170 governs), hidden beams **8Ø18/m** under C1 and **7Ø18/m** under C2, top transverse **5Ø12/m**.",ar:"**الكمرات المدفونة بتعمّقها.** تحت C1: $L_1 = 0.6 + 2\\times0.43 = 1.46$ م، و $F = 3000/(3.6\\times1.46) = 570.8$، و $z = 1.60$ م، و $M = 730.6$ kN·m/m، و $C_1 = 2.52 < 3$ ✗ (و C2: 2.71 ✗) ← $d = 4.5\\sqrt{730.6\\times10^6/25\\,000} = 769$ ← **t = 850 مم** (d = 780). دلوقتي $L_1 = 2.16$ م، و $M = 493.8$، و $C_1 = 5.55$ ✓؛ وتحت C2 $L_2 = 0.5 + 0.78 + 0.77 = 2.05$ م (القاعدة بتخلص على بعد 0.77 م بعد C2)، و $C_1 = 6.04$ ✓. القص الطولي: $Q_{cr} = 1290.3 - 1048.5\\times0.39 = 881.4$ kN، و $q = 0.314$ ✓؛ والقص الثاقب 0.632 و 0.511 < 1.29 ✓. الحديد في المتر: طولي سفلي وعلوي **6Ø16 في المتر** (الحد الأدنى 1170 هو الحاكم)، والكمرات المدفونة **8Ø18 في المتر** تحت C1 و**7Ø18 في المتر** تحت C2، وعلوي عرضي **5Ø12 في المتر**."}},{t:"note",tone:"tip",text:{en:"Detailing: long **bottom** bars hooked at both ends; long **top** bars hooked at one end only, alternating sides; the hidden-beam bars sit in the bottom mesh within $L_1$, $L_2$ under each column.",ar:"التفاصيل: الحديد الطولي **السفلي** مجنّش من الطرفين؛ والطولي **العلوي** مجنّش من طرف واحد بس، بالتبادل؛ وحديد الكمرات المدفونة في الشبكة السفلية في حدود $L_1$ و $L_2$ تحت كل عمود."}},{t:"lab",lab:"footing",height:480,props:{preset:"combined",missions:n,defaultTab:"results"},caption:{en:"Change the loads and the spacing: the resultant, the length and width, the inverted-beam diagrams below the plan and the yellow hidden-beam strips follow. The iteration line in Results shows why t grew.",ar:"غيّر الأحمال والمسافة: المحصلة والطول والعرض ومنحنيات الكمرة المقلوبة تحت المسقط وشرايح الكمرات المدفونة الصفرا بيتغيروا معاك. وسطر التكرارات في النتائج بيوضح t كبرت ليه."}},{t:"quiz",q:{kind:"num",q:{en:"P1 = 1800 kN, P2 = 1200 kN, S = 3.0 m. Distance of the resultant from C1 (m)?",ar:"P1 = 1800 kN و P2 = 1200 kN و S = 3.0 م. بُعد المحصلة عن C1 (م)؟"},answer:1.2,tol:.005,unit:"m",explain:{en:"Moments about C1: $1200\\times3.0/3000 = 1.20$ m (the resultant sits nearer the heavier column).",ar:"العزوم حوالين C1: $1200\\times3.0/3000 = 1.20$ م (المحصلة أقرب للعمود الأتقل)."}}}]},{id:"line",title:{en:"Columns at the property line: the decision and the strap beam",ar:"أعمدة حد الجار: القرار وكمرة التحزيم"},blocks:[{t:"p",text:{en:"A column on the boundary with the **neighbour** (حد الجار) cannot have a footing centred under it — half of it would stand on someone else's land. A separate footing is still possible only if it does not reach the line: $D > \\tfrac{1}{2}\\sqrt{P/q_{all}}$ (D = column axis to the line). Otherwise size the two footings as for a strap and look at the **clear gap between their P.C. bases**:",ar:"العمود اللي على حدود **الجار** مايقدرش ياخد قاعدة مركزها تحته — نصها هيبقى على أرض حد تاني. القاعدة المنفصلة لسه ممكنة بس لو ماوصلتش للحد: $D > \\tfrac{1}{2}\\sqrt{P/q_{all}}$ (D = محور العمود للحد). غير كده بنقيس القاعدتين كأنهم لكمرة تحزيم وبنبص على **المسافة الصافية بين عاديتهم**:"}},{t:"steps",items:[{en:"gap ≥ the smaller of $L_1/2$, $L_2/2$ → a **strap beam** (كمرة تحزيم) and two footings;",ar:"المسافة ≥ الأصغر من $L_1/2$ و $L_2/2$ ← **كمرة تحزيم** (كمرة رباط، Strap beam) وقاعدتين؛"},{en:"a smaller gap (or an overlap) → a **combined footing**: rectangular if the edge column is the lighter ($P_1 < P_2$), trapezoidal if it is the heavier ($P_1 > P_2$).",ar:"مسافة أصغر (أو تداخل) ← **قاعدة مشتركة**: مستطيلة لو عمود الجار هو الأخف ($P_1 < P_2$)، وشبه منحرفة لو هو الأتقل ($P_1 > P_2$)."}]},{t:"p",text:{en:"**The strap.** The edge footing F1 is pushed inside the plot: its centre is $e$ beyond the column axis (usually $e \\approx (0.1 \\to 0.2)S$), so it starts at the line with $L_1 = 2(e + D)$. The eccentricity would tip F1 over; the strap beam, tied to the interior column C2, holds it — the columns load the strap, the strap loads the two footings, the footings load the soil. Taking moments about C2:",ar:"**كمرة التحزيم.** قاعدة الجار F1 بتتزق لجوه الأرض: مركزها على بعد $e$ من محور العمود (غالباً $e \\approx (0.1 \\to 0.2)S$)، فبتبدأ من الحد بطول $L_1 = 2(e + D)$. اللامركزية دي كانت هتقلب F1؛ وكمرة التحزيم المربوطة في العمود الداخلي C2 هي اللي ماسكاها — الأعمدة بتحمّل الكمرة، والكمرة بتحمّل القاعدتين، والقاعدتين بيحمّلوا التربة. وبأخد العزوم حوالين C2:"}},{t:"eq",tex:["R_1 = \\frac{P_1\\,S}{S - e},\\qquad R_2 = P_1 + P_2 - R_1,\\qquad L_1 = 2(e + D),\\qquad B_1 = \\frac{R_1}{q_{all}\\,L_1}"],caption:{en:"R1 > P1: the strap lifts part of C2's load. On a P.C. footing F1 has no P.C. projection along L1 (it must share the R.C. centre); on a blinding the P.C. projects t_PC at the inner end only. F2 is an ordinary rectangle under R2. Preferably L1 ≥ B1 — a larger e lengthens F1.",ar:"R1 > P1: الكمرة بترفع جزء من حمل C2. ولو القاعدة العادية قاعدة (20–40 سم) F1 مفيهاش بروز عادية على طول L1 (لازم يبقى ليها نفس مركز المسلحة)؛ ولو فرشة نظافة العادية بتبرز t_PC من الطرف الداخلي بس. و F2 مستطيل عادي تحت R2. ويفضّل L1 ≥ B1 — e أكبر بتطوّل F1."}},{t:"eq",tex:["w_1 = \\frac{1.5R_1}{L_1},\\qquad X_0 = \\frac{P_{1u}}{w_1},\\qquad M^{-} = P_{1u}(X_0 - D) - \\frac{w_1 X_0^2}{2},\\qquad M^{+} = \\frac{w_2\\,(L_2/2)^2}{2}"],caption:{en:"The strap as a beam: the largest (top-tension) moment at zero shear over F1, a constant shear between the footings, bottom tension under C2.",ar:"كمرة التحزيم ككمرة: أكبر عزم (شد فوق) عند القص = صفر فوق F1، وقص ثابت بين القاعدتين، وشد تحت تحت C2."}},{t:"note",tone:"code",text:{en:"**Strap section:** b = 400–1000 mm, not narrower than the columns (b ≈ d/2 recommended), $d = C_1\\sqrt{M/(f_{cu}b)}$. **Shear** with the values used for this beam: $q_{cu} = 0.24\\sqrt{f_{cu}/\\gamma_c}$, $q_{max} = 0.70\\sqrt{f_{cu}/\\gamma_c}$; below $q_{cu}$ minimum stirrups 5Ø10/m, above it $q_{su} = q_u - q_{cu}/2$; four legs when b > 400 mm. **Bars:** top bars over the full length, hooked at both ends; bottom bars under C2 (at least the beam minimum). The footings are designed as **strip footings** cantilevering from the beam faces, their main mesh running across the beam (no punching: the columns stand on the beam). **Shapes:** footing bottoms level with the beam bottom (most used, least excavation), footings deeper than the beam (not preferred), or a much deeper founding layer.",ar:"**قطاع الكمرة:** b من 400 لـ 1000 مم، ومش أضيق من الأعمدة (يفضّل b ≈ d/2)، و $d = C_1\\sqrt{M/(f_{cu}b)}$. **القص** بالقيم المستخدمة للكمرة دي: $q_{cu} = 0.24\\sqrt{f_{cu}/\\gamma_c}$، و $q_{max} = 0.70\\sqrt{f_{cu}/\\gamma_c}$؛ تحت $q_{cu}$ كانات دنيا 5Ø10 في المتر، وفوقه $q_{su} = q_u - q_{cu}/2$؛ وأربع فروع لما b > 400 مم. **الحديد:** العلوي بطول الكمرة كلها ومجنّش من الطرفين؛ والسفلي تحت C2 (على الأقل الحد الأدنى للكمرات). والقواعد بتتصمم **كقواعد شريطية** كابولي من وشوش الكمرة، وشبكتها الرئيسية عمودية على الكمرة (مفيش قص ثاقب: الأعمدة واقفة على الكمرة). **الأشكال:** بطن القواعد على نفس منسوب بطن الكمرة (الأكثر استخداماً وأقل حفر)، أو القواعد أوطى من الكمرة (مش مفضّل)، أو طبقة تأسيس أوطى بكتير."}},{t:"p",text:{en:"**Example.** Edge column 400 × 400 mm at the line ($D = 0.20$ m), $P_1 = 850$ kN; C2 400 × 600 mm, $P_2 = 1750$ kN; $S = 6.0$ m; $q_{all} = 180$; P.C. 30 cm. $D = 0.20 < \\tfrac{1}{2}\\sqrt{850/180} = 1.087$ → no separate footing. $e = 0.9$ m: $R_1 = 850\\times6/5.1 = 1000$ kN, $R_2 = 1600$ kN; $L_1 = 2.20$ m, $B_1 = 1000/(180\\times2.2) = 2.53$ → **P.C. 2.60, R.C. 2.00 × 2.20**; F2 **P.C. 2.90 × 3.10, R.C. 2.30 × 2.50**. Gap $= 0.2 + 6.0 - 1.55 - 2.20 = 2.45 \\ge 1.10$ → **strap** ✓. $w_1 = 681.8$, $w_2 = 960$ kN/m, $X_0 = 1.87$ m, $M^- = 937.1$, $M^+ = 750.0$ kN·m. With b = 600: $d = 1250$ → **t = 1350 mm**; shear $Q_{cr} = 1002.3 - 681.8\\times0.64 = 565.9$ kN, $q = 0.737 < q_{cu} = 0.98$ → **5Ø10/m, 4 legs**; top **6Ø22** (2216 mm²), bottom **6Ø22** (the beam minimum 2160 mm² governs). F1 as a strip: $z = 0.70$, $M = 83.5$ kN·m/m, t = 400, **7Ø12/m**; F2: $z = 0.85$, $M = 150.8$, t = 500, **6Ø16/m**.",ar:"**مثال.** عمود الجار 400 × 400 مم عند الحد ($D = 0.20$ م)، و $P_1 = 850$ kN؛ و C2 400 × 600 مم، و $P_2 = 1750$ kN؛ و $S = 6.0$ م؛ و $q_{all} = 180$؛ وعادية 30 سم. $D = 0.20 < \\tfrac{1}{2}\\sqrt{850/180} = 1.087$ ← مفيش قاعدة منفصلة. $e = 0.9$ م: $R_1 = 850\\times6/5.1 = 1000$ kN، و $R_2 = 1600$ kN؛ و $L_1 = 2.20$ م، و $B_1 = 1000/(180\\times2.2) = 2.53$ ← **العادية 2.60 والمسلحة 2.00 × 2.20**؛ و F2 **العادية 2.90 × 3.10 والمسلحة 2.30 × 2.50**. المسافة $= 0.2 + 6.0 - 1.55 - 2.20 = 2.45 \\ge 1.10$ ← **كمرة تحزيم** ✓. $w_1 = 681.8$ و $w_2 = 960$ kN/m، و $X_0 = 1.87$ م، و $M^- = 937.1$ و $M^+ = 750.0$ kN·m. وبـ b = 600: $d = 1250$ ← **t = 1350 مم**؛ والقص $Q_{cr} = 1002.3 - 681.8\\times0.64 = 565.9$ kN، و $q = 0.737 < q_{cu} = 0.98$ ← **5Ø10 في المتر، 4 فروع**؛ وعلوي **6Ø22** (2216 مم²)، وسفلي **6Ø22** (الحد الأدنى للكمرات 2160 مم² هو الحاكم). F1 كقاعدة شريطية: $z = 0.70$، و $M = 83.5$ kN·m/m، و t = 400، و**7Ø12 في المتر**؛ و F2: $z = 0.85$، و $M = 150.8$، و t = 500، و**6Ø16 في المتر**."}},{t:"lab",lab:"footing",height:480,props:{preset:"strap",missions:o,defaultTab:"results"},caption:{en:"The decision tree lights the path of your numbers. Slide e: R1 = P1·S/(S − e) grows, F1 gets longer and narrower and the strap moment climbs. Shorten S to watch the gap test fail.",ar:"شجرة القرار بتنوّر طريق أرقامك. حرّك e: R1 = P1·S/(S − e) بيكبر، و F1 بتطول وتضيق، وعزم الكمرة بيعلى. وقصّر S عشان تشوف اختبار المسافة بيفشل."}},{t:"quiz",q:{kind:"num",q:{en:"Edge column P1 = 900 kN, S = 5.0 m, e = 0.75 m. R1 (kN)?",ar:"عمود الجار P1 = 900 kN، و S = 5.0 م، و e = 0.75 م. R1 (kN)؟"},answer:1058.82,tol:.003,unit:"kN",explain:{en:"$R_1 = 900\\times5.0/(5.0 - 0.75) = 4500/4.25 = 1058.8$ kN.",ar:"$R_1 = 900\\times5.0/(5.0 - 0.75) = 4500/4.25 = 1058.8$ kN."}}}]},{id:"linecombined",title:{en:"Combined footings at the property line: rectangle or trapezoid",ar:"القواعد المشتركة عند حد الجار: مستطيل ولا شبه منحرف"},blocks:[{t:"p",text:{en:"**Rectangular (P1 < P2).** The footing starts at the line and its centre sits on the resultant, so its length is fixed: $L/2 = (S - X) + D$. It has **no P.C. projection along L** (keeps both centres on R). The hidden beam of the edge column spreads to one side only, $L_1 = b_1 + d$, and that column punches on **three faces with α = 3**; its (smaller) $q_{pcu}$ is used for both columns.",ar:"**مستطيلة (P1 < P2).** القاعدة بتبدأ من الحد ومركزها على المحصلة، فطولها متحدد: $L/2 = (S - X) + D$. **مفيش بروز عادية على طول L** (عشان المركزين يفضلوا على R). والكمرة المدفونة لعمود الجار بتتوزع لناحية واحدة بس، $L_1 = b_1 + d$، والعمود ده بيثقب على **تلات وشوش بـ α = 3**؛ و $q_{pcu}$ بتاعه (الأصغر) بيستخدم للعمودين."}},{t:"eq",tex:["\\frac{L}{2} = (S - X) + D,\\qquad Q_p = P_{1u} - F(a_1 + d)\\left(b_1 + \\frac{d}{2}\\right),\\qquad b_o = (a_1 + d) + 2\\left(b_1 + \\frac{d}{2}\\right)"],caption:{en:"X = P1·S/R measured from C2; the edge column (a1 along the line, b1 across it) touches the line.",ar:"X = P1·S/R مقاسة من C2؛ وعمود الجار (a1 موازي للحد و b1 عمودي عليه) لازق في الحد."}},{t:"p",text:{en:"**Example (same columns, S = 3.6 m).** Trial strap with e = 0.7: $L_1 = 1.80$, F2 P.C. 3.05 m long → gap $= 0.2 + 3.6 - 1.525 - 1.80 = 0.475 < 0.90$ ✗ → combined, $P_1 < P_2$ → rectangular. $R = 2600$ kN, $X = 850\\times3.6/2600 = 1.177$ m, $L/2 = 2.423 + 0.2$ → **L = 5.25 m**, $B_{PC} = 2600/(180\\times5.25) = 2.75$ → **2.80**, $B_{RC} = 2.20$ m; $w = 742.9$ kN/m. Zero shear at $X_0 = 1275/742.9 = 1.716$ m: $M^- = 839.2$ kN·m (top); 483.7 kN·m at C2's outer face. $d = 617.6$ → t = 700, but the long shear ($Q_{max} = 1325$ kN at C2's inner face) fails twice: $q = 0.787$ (t = 700), 0.656 (t = 800) → **t = 900 mm**, $q = 0.557$ ✓. Edge punching: $Q_p = 936.5$ kN, $b_o = 2860$ mm, $q_{pu} = 0.395 < 1.29$ ✓.",ar:"**مثال (نفس الأعمدة، S = 3.6 م).** تجربة كمرة تحزيم بـ e = 0.7: $L_1 = 1.80$ وعادية F2 طولها 3.05 م ← المسافة $= 0.2 + 3.6 - 1.525 - 1.80 = 0.475 < 0.90$ ✗ ← مشتركة، و $P_1 < P_2$ ← مستطيلة. $R = 2600$ kN، و $X = 850\\times3.6/2600 = 1.177$ م، و $L/2 = 2.423 + 0.2$ ← **L = 5.25 م**، و $B_{PC} = 2600/(180\\times5.25) = 2.75$ ← **2.80**، و $B_{RC} = 2.20$ م؛ و $w = 742.9$ kN/m. القص = صفر عند $X_0 = 1275/742.9 = 1.716$ م: $M^- = 839.2$ kN·m (فوق)؛ و 483.7 kN·m عند وش C2 الخارجي. $d = 617.6$ ← t = 700، بس القص الطولي ($Q_{max} = 1325$ kN عند وش C2 الداخلي) بيفشل مرتين: $q = 0.787$ (t = 700) و 0.656 (t = 800) ← **t = 900 مم**، و $q = 0.557$ ✓. القص الثاقب للطرف: $Q_p = 936.5$ kN، و $b_o = 2860$ مم، و $q_{pu} = 0.395 < 1.29$ ✓."}},{t:"p",text:{en:"**Trapezoidal (P1 > P2)** — the rare case. The heavier edge column pulls the resultant toward the line; a rectangle starting at the line cannot have its centre there, so the footing is made **wider at the line**. Choose $L = D + S + (0.5 \\to 1.0)$; locate the resultant from the line, $X_T = X_R + D$ with $X_R = P_2 S/R$ from the edge column; then area and centroid give the two widths:",ar:"**شبه منحرفة (P1 > P2)** — الحالة النادرة. عمود الجار الأتقل بيشد المحصلة ناحية الحد؛ ومستطيل بيبدأ من الحد مايقدرش يبقى مركزه هناك، فالقاعدة بتتعمل **أعرض عند الحد**. خد $L = D + S + (0.5 \\to 1.0)$؛ وحدد المحصلة من الحد، $X_T = X_R + D$ حيث $X_R = P_2 S/R$ من عمود الجار؛ وبعدين المساحة ومركز الثقل بيدوا العرضين:"}},{t:"eq",tex:["A = \\frac{R}{q_{all}} = L\\,\\frac{B_1 + B_2}{2},\\qquad X_T = \\frac{L}{3}\\,\\frac{B_1 + 2B_2}{B_1 + B_2}"],caption:{en:"B1 at the line (wide end), B2 at the far end; valid only with L/3 < X_T < L/2. Hidden beams use the local average widths; long bars per metre of the local width.",ar:"B1 عند الحد (الطرف العريض) و B2 عند الطرف البعيد؛ وصالح بس لو L/3 < X_T < L/2. والكمرات المدفونة بتاخد متوسط العرض المحلي؛ والحديد الطولي لكل متر من العرض المحلي."}},{t:"p",text:{en:"**Example.** Edge column $P_1 = 1200$ kN, $P_2 = 1100$ kN, $S = 4.0$, $D = 0.2$, $q_{all} = 180$; the trial strap (e = 1.0) leaves a gap of 0.80 < 1.00 → combined, and $P_1 > P_2$ → trapezoid. $L = 0.2 + 4.0 + 0.6 = 4.80$ m, $X_R = 1100\\times4/2300 = 1.913$, $X_T = 2.113$ m; $A = 12.78$ m² → $B_1 + B_2 = 5.324$, $(B_1 + 2B_2)/(B_1 + B_2) = 3\\times2.113/4.8 = 1.321$ → **B1 = 3.62, B2 = 1.71 m** on the P.C. (R.C. 2.80 and 1.32 m, keeping its centroid on the resultant).",ar:"**مثال.** عمود الجار $P_1 = 1200$ kN، و $P_2 = 1100$ kN، و $S = 4.0$، و $D = 0.2$، و $q_{all} = 180$؛ تجربة كمرة التحزيم (e = 1.0) بتسيب مسافة 0.80 < 1.00 ← مشتركة، و $P_1 > P_2$ ← شبه منحرف. $L = 0.2 + 4.0 + 0.6 = 4.80$ م، و $X_R = 1100\\times4/2300 = 1.913$، و $X_T = 2.113$ م؛ و $A = 12.78$ م² ← $B_1 + B_2 = 5.324$، و $(B_1 + 2B_2)/(B_1 + B_2) = 3\\times2.113/4.8 = 1.321$ ← **B1 = 3.62 و B2 = 1.71 م** على العادية (المسلحة 2.80 و 1.32 م، ومحافظة على مركز ثقلها على المحصلة)."}},{t:"quiz",q:{kind:"num",q:{en:"A trapezoid 6.0 m long with B1 = 3.0 m and B2 = 1.5 m. Distance of its centroid from the wide end (m)?",ar:"شبه منحرف طوله 6.0 م و B1 = 3.0 م و B2 = 1.5 م. بُعد مركز ثقله عن الطرف العريض (م)؟"},answer:2.667,tol:.003,unit:"m",explain:{en:"$X = (6/3)(3.0 + 2\\times1.5)/(3.0 + 1.5) = 2\\times6/4.5 = 2.667$ m — between L/3 = 2 and L/2 = 3, as it must be.",ar:"$X = (6/3)(3.0 + 2\\times1.5)/(3.0 + 1.5) = 2\\times6/4.5 = 2.667$ م — بين L/3 = 2 و L/2 = 3 زي ما لازم."}}}]},{id:"apply",title:{en:"Your building: footings, and a neighbour along axis 1",ar:"مبناك: القواعد، وجار على المحور 1"},blocks:[{t:"p",text:{en:"Your building stands on a soil with $q_{all} = 150$ kN/m², fcu = 25, fy = 400, founding level −1.50, and every footing on a **30 cm P.C. footing**. Now the realistic part: the plot next door runs along **axis 1**, so the columns **A1, B1 and C1** stand at the property line with their outer 0.30 m face on it — $D = 0.15$ m. Their service loads are 178.9, 293.2 and 123.9 kN, and $\\tfrac{1}{2}\\sqrt{P/150} = 0.546$, 0.699 and 0.454 m — all larger than 0.15: **no separate footings** at the line.",ar:"مبناك قاعد على تربة $q_{all} = 150$ kN/m²، و fcu = 25، و fy = 400، ومنسوب التأسيس −1.50، وكل قاعدة على **قاعدة عادية 30 سم**. ودلوقتي الجزء الواقعي: أرض الجار ماشية على **المحور 1**، يعني الأعمدة **A1 و B1 و C1** واقفة على حد الجار ووشها الخارجي (0.30 م) لازق فيه — $D = 0.15$ م. أحمال التشغيل بتاعتهم 178.9 و 293.2 و 123.9 kN، و $\\tfrac{1}{2}\\sqrt{P/150} = 0.546$ و 0.699 و 0.454 م — كلهم أكبر من 0.15: **مفيش قواعد منفصلة** عند الحد."}},{t:"p",text:{en:"**The decision.** With $e = 0.1S = 0.5$ m ($S = 5.0$ m to axis 2 — light columns, so a short F1 is enough and the strap moment stays small) F1 is 1.30 m long and the gaps to F2 are 3.10, 3.00 and 3.15 m, far above $\\min(L_1, L_2)/2 = 0.65$ m → **three strap beams A1–A2, B1–B2 and C1–C2** along x. Row B: $R_1 = 293.2\\times5/4.5 = 325.8$ kN, $R_2 = 459.5$ kN; F1 **R.C. 1.30 × 1.10** (P.C. 1.30 × 1.70); F2 **R.C. 1.10 × 1.30** (P.C. 1.70 × 1.90); the 500 mm strap carries $M^- = 191.3$ and $M^+ = 94.8$ kN·m → $d = 619$ → **500 × 700**, top **5Ø16**, bottom **3Ø16**, $q = 0.662 < 0.98$ → **5Ø10/m, 4 legs**. The footings under the straps need only t = 400 and **5Ø12/m**; in rows A and C the 0.80 m minimum governs F1 (and F2 of row C), with straps 500 × 600 and 500 × 500.",ar:"**القرار.** بـ $e = 0.1S = 0.5$ م ($S = 5.0$ م للمحور 2 — أعمدة خفيفة، فـ F1 قصيرة كفاية وعزم الكمرة بيفضل صغير) طول F1 بيبقى 1.30 م والمسافات لـ F2 بتبقى 3.10 و 3.00 و 3.15 م، أكبر بكتير من $\\min(L_1, L_2)/2 = 0.65$ م ← **تلات كمرات تحزيم A1–A2 و B1–B2 و C1–C2** في اتجاه x. الصف B: $R_1 = 293.2\\times5/4.5 = 325.8$ kN، و $R_2 = 459.5$ kN؛ و F1 **مسلحة 1.30 × 1.10** (عادية 1.30 × 1.70)؛ و F2 **مسلحة 1.10 × 1.30** (عادية 1.70 × 1.90)؛ والكمرة عرضها 500 مم شايلة $M^- = 191.3$ و $M^+ = 94.8$ kN·m ← $d = 619$ ← **500 × 700**، وعلوي **5Ø16** وسفلي **3Ø16**، و $q = 0.662 < 0.98$ ← **5Ø10 في المتر، 4 فروع**. والقواعد اللي تحت الكمرات محتاجة t = 400 بس و**5Ø12 في المتر**؛ وفي الصفين A و C الحد الأدنى 0.80 م هو اللي حاكم F1 (و F2 في الصف C)، بكمرات 500 × 600 و 500 × 500."}},{t:"table",head:[{en:"Footing",ar:"القاعدة"},"P (kN)",{en:"P.C. (m)",ar:"العادية (م)"},{en:"R.C. (m)",ar:"المسلحة (م)"},"t (mm)",{en:"Bars",ar:"الحديد"}],rows:[["B3","431.5","1.60 × 1.80","1.00 × 1.20","400","5Ø12/m"],[{en:"A3, A4, B4, C3, C4",ar:"A3 و A4 و B4 و C3 و C4"},"104.5–289.5","1.40 × 1.60",{en:"0.80 × 1.00 (minimum)",ar:"0.80 × 1.00 (الحد الأدنى)"},"400","5Ø12/m"],[{en:"B1 (F1 of the strap)",ar:"B1 (F1 للكمرة)"},"293.2","1.30 × 1.70","1.30 × 1.10","400","5Ø12/m"],[{en:"B2 (F2 of the strap)",ar:"B2 (F2 للكمرة)"},"492.1","1.70 × 1.90","1.10 × 1.30","400","5Ø12/m"]],caption:{en:"Isolated footings: equal projections (L − B = 0.5 − 0.3 = 0.2 m), L along z. B3 needs 1.00 × 1.20 m; the lighter columns sit on the minimum. Levels: foundation −1.50, top P.C. −1.20, top R.C. −0.80, top of the B-strap −0.50.",ar:"القواعد المنفصلة: بروزات متساوية (L − B = 0.5 − 0.3 = 0.2 م)، و L في اتجاه z. B3 محتاجة 1.00 × 1.20 م؛ والأعمدة الأخف على الحد الأدنى. المناسيب: التأسيس −1.50، وظهر العادية −1.20، وظهر المسلحة −0.80، وظهر كمرة الصف B −0.50."}},{t:"p",text:{en:"A light two-storey building: almost every footing sits on the code minimums (0.80 m, 400 mm, 5Ø12/m) — exactly why those minimums matter in practice. The only elements that really had to be designed are the three straps at the neighbour.",ar:"مبنى خفيف من دورين: تقريباً كل القواعد قاعدة على الحدود الدنيا للكود (0.80 م و 400 مم و 5Ø12 في المتر) — وده بالظبط سبب أهمية الحدود الدنيا دي في الشغل. والعناصر الوحيدة اللي اتصممت فعلاً هي كمرات التحزيم التلاتة عند الجار."}},{t:"lab",lab:"footing",height:500,props:{preset:"building",missions:i,defaultTab:"results"},caption:{en:"The B1–B2 strap of your building in the lab (P1 = 293.2, P2 = 492.1 kN, S = 5.0 m, e = 0.5 m, b = 500 mm).",ar:"كمرة التحزيم B1–B2 بتاعة مبناك في المعمل (P1 = 293.2 و P2 = 492.1 kN، و S = 5.0 م، و e = 0.5 م، و b = 500 مم)."}},{t:"widget",w:"building",props:{focus:"F-B1",tags:["footings","cols-g","materials","footing-design"]}},{t:"quiz",q:{kind:"mcq",q:{en:"Why does column B1 get a strap beam and not a combined footing with B2?",ar:"ليه العمود B1 خد كمرة تحزيم ومش قاعدة مشتركة مع B2؟"},options:[{en:"The clear gap between the two P.C. bases (3.00 m) exceeds min(L1, L2)/2 = 0.65 m",ar:"المسافة الصافية بين العاديتين (3.00 م) أكبر من min(L1, L2)/2 = 0.65 م"},{en:"B1 is heavier than B2",ar:"B1 أتقل من B2"},{en:"D = 0.15 m is larger than ½√(P/q_all)",ar:"D = 0.15 م أكبر من ½√(P/q_all)"}],answer:0,explain:{en:"D = 0.15 < 0.699 rules out a separate footing; the wide gap then chooses the strap. A combined footing is for footings that come too close or overlap.",ar:"D = 0.15 < 0.699 بتلغي القاعدة المنفصلة؛ وبعدين المسافة الكبيرة بتختار كمرة التحزيم. القاعدة المشتركة للقواعد اللي بتقرّب قوي أو بتتداخل."}}}]}],quiz:[{kind:"num",q:{en:"P = 1500 kN, q_all = 200 kN/m², a square footing on a 30 cm P.C. footing. B_RC (m)?",ar:"P = 1500 kN و q_all = 200 kN/m²، قاعدة مربعة على قاعدة عادية 30 سم. B_RC (م)؟"},answer:2.15,tol:.005,unit:"m",explain:{en:"$A = 7.5$ m², $\\sqrt{7.5} = 2.739$ → $B_{PC} = 2.75$ m, $B_{RC} = 2.75 - 0.60 = 2.15$ m.",ar:"$A = 7.5$ م² و $\\sqrt{7.5} = 2.739$ ← $B_{PC} = 2.75$ م، و $B_{RC} = 2.75 - 0.60 = 2.15$ م."}},{kind:"mcq",q:{en:"The plain concrete under a footing is 15 cm thick. The area P/q_all is computed on…",ar:"الخرسانة العادية تحت القاعدة تخانتها 15 سم. المساحة P/q_all بتتحسب على…"},options:[{en:"the R.C. — a blinding is ignored, and the P.C. projects 15 cm around",ar:"المسلحة — فرشة النظافة بتتهمل، والعادية بتبرز حواليها 15 سم"},{en:"the P.C.",ar:"العادية"},{en:"the average of both",ar:"متوسط الاتنين"}],answer:0,explain:{en:"10–20 cm is a blinding: the R.C. carries the area. From 20 to 40 cm the P.C. is a footing and carries it.",ar:"من 10 لـ 20 سم فرشة نظافة: المسلحة هي اللي بتاخد المساحة. ومن 20 لـ 40 سم العادية قاعدة وبتاخدها."}},{kind:"num",q:{en:"Column 0.30 × 0.90 m, fcu = 25. The column-shape punching limit 0.316(0.5 + a/b)√(fcu/γc) (N/mm²)?",ar:"عمود 0.30 × 0.90 م، و fcu = 25. حد القص الثاقب اللي بيعتمد على شكل العمود 0.316(0.5 + a/b)√(fcu/γc) (N/mm²)؟"},answer:1.075,tol:.003,unit:"N/mm²",explain:{en:"$0.316(0.5 + 0.333)\\times4.082 = 1.075$ N/mm² — below 0.316√(fcu/γc) = 1.29, so it governs.",ar:"$0.316(0.5 + 0.333)\\times4.082 = 1.075$ N/mm² — أقل من 0.316√(fcu/γc) = 1.29، فهو الحاكم."}},{kind:"num",q:{en:"P = 1200 kN, temporary M = 300 kN·m along the 3.2 m side of a 2.8 × 3.2 m base. F2 (kN/m²)?",ar:"P = 1200 kN، وعزم مؤقت M = 300 kN·m في اتجاه الضلع 3.2 م لقاعدة 2.8 × 3.2 م. F2 (kN/m²)؟"},answer:71.15,tol:.005,unit:"kN/m²",explain:{en:"$1200/8.96 - 6\\times300/(2.8\\times3.2^2) = 133.93 - 62.78 = 71.15$ kN/m².",ar:"$1200/8.96 - 6\\times300/(2.8\\times3.2^2) = 133.93 - 62.78 = 71.15$ kN/m²."}},{kind:"tf",q:{en:"A permanent moment is handled by moving the column off the footing centre.",ar:"العزم الدائم بيتعالج بإننا نزق العمود بعيد عن مركز القاعدة."},answer:!1,explain:{en:"The column stays on its axis; the footing is shifted by e = M/P so that the resultant passes through its centre.",ar:"العمود بيفضل على محوره؛ القاعدة هي اللي بتترحّل e = M/P عشان المحصلة تعدّي بمركزها."}},{kind:"num",q:{en:"Strap beam: P1 = 700 kN, S = 5.5 m, e = 0.8 m. R1 (kN)?",ar:"كمرة تحزيم: P1 = 700 kN، و S = 5.5 م، و e = 0.8 م. R1 (kN)؟"},answer:819.15,tol:.003,unit:"kN",explain:{en:"$700\\times5.5/(5.5 - 0.8) = 3850/4.7 = 819.1$ kN.",ar:"$700\\times5.5/(5.5 - 0.8) = 3850/4.7 = 819.1$ kN."}},{kind:"mcq",q:{en:"An isolated footing needs a top mesh of 5Ø12/m when…",ar:"القاعدة المنفصلة محتاجة شبكة علوية 5Ø12 في المتر لما…"},options:[{en:"t ≥ 1.0 m",ar:"t ≥ 1.0 م"},{en:"the column is rectangular",ar:"العمود مستطيل"},{en:"P.C. ≥ 30 cm",ar:"العادية ≥ 30 سم"}],answer:0,explain:{en:"A thick footing gets a top shrinkage mesh; below 1.0 m the bottom mesh alone is used.",ar:"القاعدة التخينة بتاخد شبكة انكماش علوية؛ وتحت 1.0 م الشبكة السفلية لوحدها."}},{kind:"num",q:{en:"Combined footing: P1 = 1500 kN (heavier), P2 = 1000 kN with b2 = 0.40 m along the line, S = 3.0 m, 0.75 m beyond C2. L_RC (m)?",ar:"قاعدة مشتركة: P1 = 1500 kN (الأتقل)، و P2 = 1000 kN و b2 = 0.40 م على الخط، و S = 3.0 م، و 0.75 م بعد C2. L_RC (م)؟"},answer:5.5,tol:.005,unit:"m",explain:{en:"$X = 1500\\times3/2500 = 1.80$ m from C2; $L/2 = 1.80 + 0.20 + 0.75 = 2.75$ → L = 5.50 m.",ar:"$X = 1500\\times3/2500 = 1.80$ م من C2؛ و $L/2 = 1.80 + 0.20 + 0.75 = 2.75$ ← L = 5.50 م."}}]};export{s as default};
